                                ('step 1');
                                if (event.lists.length) {
                                    event.cardss = event.lists.shift();
                                    var cards = event.cardss;
                                    var info = get.info(cards);
                                    var select = get.select(info.selectTarget);
                                    if (['delay', 'equip'].includes(get.type(cards))) event.num = [1, 1];
                                    else if (info.toself) event.num = [1, 1];
                                    else if (select[1] == -1 && !info.toself) {
                                        if (info.filterTarget == true) {
                                            event.num = [1, game.players.length];
                                        } else if (typeof info.filterTarget == 'function') {
                                            if (info.filterTarget(null, player, player)) event.num = [1, game.players.length];
                                            else event.num = [1, game.players.length - 1];
                                        }
                                    } else event.num = get.select(info.selectTarget);
                                    player.showHandcards();
                                    player
                                        .chooseTarget('使用' + get.translation(cards), [event.num[0], event.num[1]], function (card, player, target) {
                                            return player.canUse(cards, target);
                                        })
                                        .set('ai', function (target) {
                                            if (cards.name == 'lg_jingong' || cards.name == 'lg_shanbi') return get.attitude(player, target) <= 0;
                                            if (cards.name == 'lg_kuangbao' || cards.name == 'lg_zhiyu') return get.attitude(player, target) > 0;
                                            return get.effect(target, cards, player, player);
                                        });
                                } else event.finish();
                                ('step 2');
                                if (result.bool) {
                                    var target = result.targets;
                                    var card = event.cardss;
                                    if (event.nh == 0) {
                                        event.nh++;
                                    }
                                    var targets = [];
                                    for (var i = 0; i < target.length; i++) {
                                        targets.push(target[i]);
                                    }
                                    player.useCard(card, targets).animate = false;
                                    event.goto(1);
                                } else event.goto(1);
