                        lg_tanya: ['female', '乐园之隙', 7, ['lg_zhanzhengzhihui', 'lg_diguolixing'], []],
                        lg_luluxiu: ['male', '乐园之隙', 6, ['lg_zhanshuzhihui', 'lg_jueduifucong'], []],
