                        lg_yueer: ['female', '乐园之隙', '6/7', ['lg_jingjigongzhu', 'lg_shashou', 'lg_jueyi'], []],
                        lg_tuoer: ['female', '乐园之隙', 6, ['lg_longji'], []],
